  'Tìm chùa hoặc tỉnh': ['Search pagoda or province', '搜索寺院或省份', 'Pagode oder Provinz suchen'],
  '{0} chùa · {1} đã dựng': ['{0} pagodas · {1} built', '{0}座寺院 · 已建{1}座', '{0} Pagoden · {1} gebaut'],
  'Miền Bắc': ['North', '北部', 'Norden'],
